algorithm = 'pid'
@pytest.mark.parametrize('algorithm', ['pid', 'lqr', 'adrc']) def test_control_waits_for_clock_sample_without_cutting_thrust_or_reintegrating(algorithm): """A slow Gazebo clock may stay unchanged across several wall timer ticks.""" with control_harness(extra_args=('-p', 'usv_simulation.controller.controller_name:=' + algorithm)) as h: h.ready() h.send_reference() h.until(lambda: h.control.mode == 'NAVIGATING') h.control.control_timer.cancel() for _ in range(5): h.step() h.control._control() previous = h.control.last_published_command assert previous.left > 0 and previous.right > 0 if algorithm == 'adrc': core = h.control.controller integral = core.speed_loop.integral_speed history = list(core.heading_loop.heading_filter.position_history) # Same ROS time, no new observation: keep output, never run the core twice. h.control._control() > assert h.control.mode == 'NAVIGATING' E AssertionError: assert 'SIMULATION_PAUSED' == 'NAVIGATING' E - NAVIGATING E + SIMULATION_PAUSED
